CREATE OR REPLACE FUNCTION public.prevent_locked_stage_run_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    old_locked_at timestamptz;
    new_locked_at timestamptz;
    old_post_run_evidence boolean;
    new_post_run_evidence boolean;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT run.scientific_evidence_locked_at INTO new_locked_at
        FROM experiments AS run
        WHERE run.id = NEW.pipeline_run_id;
        new_post_run_evidence := NEW.stage_type = 'verification'
            OR NEW.stage_key IN ('deterministic_verification', 'report', 'openai_audit');
        IF new_locked_at IS NOT NULL AND NOT new_post_run_evidence THEN
            RAISE EXCEPTION
                'pipeline_stage_runs is frozen: scientific evidence for this pipeline run is locked';
        END IF;
        RETURN NEW;
    END IF;

    SELECT run.scientific_evidence_locked_at INTO old_locked_at
    FROM experiments AS run
    WHERE run.id = OLD.pipeline_run_id;
    old_post_run_evidence := OLD.stage_type = 'verification'
            OR OLD.stage_key IN ('deterministic_verification', 'report', 'openai_audit');

    IF TG_OP = 'DELETE' THEN
        IF old_locked_at IS NOT NULL
            AND NOT old_post_run_evidence
            AND OLD.status IN ('completed', 'failed', 'skipped')
        THEN
            RAISE EXCEPTION
                'pipeline_stage_runs is frozen: scientific evidence for this pipeline run is locked';
        END IF;
        RETURN OLD;
    END IF;

    SELECT run.scientific_evidence_locked_at INTO new_locked_at
    FROM experiments AS run
    WHERE run.id = NEW.pipeline_run_id;
    new_post_run_evidence := NEW.stage_type = 'verification'
        OR NEW.stage_key IN ('deterministic_verification', 'report', 'openai_audit');

    IF old_locked_at IS NOT NULL AND NOT old_post_run_evidence THEN
        IF OLD.status IN ('completed', 'failed', 'skipped')
            OR NEW.pipeline_run_id IS DISTINCT FROM OLD.pipeline_run_id
            OR NEW.stage_key IS DISTINCT FROM OLD.stage_key
            OR NEW.stage_type IS DISTINCT FROM OLD.stage_type
            OR NEW.status NOT IN ('completed', 'failed', 'skipped')
        THEN
            RAISE EXCEPTION
                'pipeline_stage_runs is frozen: scientific evidence for this pipeline run is locked';
        END IF;
    END IF;

    IF new_locked_at IS NOT NULL AND NOT new_post_run_evidence
        AND (
            NEW.pipeline_run_id IS DISTINCT FROM OLD.pipeline_run_id
            OR old_post_run_evidence
        )
    THEN
        RAISE EXCEPTION
            'pipeline_stage_runs is frozen: scientific evidence for this pipeline run is locked';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_mutation_except_retention()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    xact text := coalesce(current_setting('dclab.retention_xact', true), '');
    horizon text := coalesce(current_setting('dclab.retention_horizon', true), '');
    retention_workspace text := coalesce(current_setting('dclab.retention_workspace', true), '');
    deleting text := coalesce(current_setting('dclab.deleting_workspace', true), '');
    permitted boolean := false;
BEGIN
    IF TG_OP = 'DELETE' OR (TG_NARGS > 0 AND TG_ARGV[0] = 'retention_update') THEN
        IF xact <> '' THEN
            IF xact = pg_current_xact_id()::text THEN
                IF horizon <> '' AND retention_workspace <> '' THEN
                    IF horizon::interval >= interval '30 days' THEN
                        permitted := coalesce(
                            retention_workspace::uuid = OLD.workspace_id
                            AND OLD.created_at < now() - horizon::interval,
                            false
                        );
                    END IF;
                END IF;
                IF NOT permitted AND deleting <> '' THEN
                    permitted := coalesce(deleting::uuid = OLD.workspace_id, false);
                END IF;
            END IF;
        END IF;
    END IF;
    IF NOT permitted THEN
        RAISE EXCEPTION '% rows are append-only outside retention', TG_TABLE_NAME;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_visualization_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'visualizations rows are immutable';
    END IF;
    IF (to_jsonb(OLD) - 'project_id' - 'pipeline_stage_run_id'
            - 'candidate_id' - 'model_evaluation_id')
        IS DISTINCT FROM
       (to_jsonb(NEW) - 'project_id' - 'pipeline_stage_run_id'
            - 'candidate_id' - 'model_evaluation_id')
    THEN
        RAISE EXCEPTION 'visualizations identity/spec is immutable';
    END IF;
    RETURN NEW;
END;
$function$
